import React, { useState, useEffect, useRef, useCallback } from 'react';
import { motion } from 'framer-motion';
import { 
  Plus, 
  Save, 
  Menu, 
  X, 
  LogOut,
  FileText
} from 'lucide-react';
import axios from 'axios';

const API_URL = 'http://localhost:5000';

function App() {
  const [notes, setNotes] = useState([]);
  const [activeTab, setActiveTab] = useState(null);
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [sidebarOpen, setSidebarOpen] = useState(true);
  const textareaRef = useRef(null);

  const handleAuthCallback = useCallback(async (code) => {
    try {
      const response = await axios.post(`${API_URL}/auth/google/callback`, { code });
      if (response.data && response.data.tokens) {
        localStorage.setItem('googleTokens', JSON.stringify(response.data.tokens));
        setIsAuthenticated(true);
        const notesResponse = await axios.get(`${API_URL}/api/notes`, {
          headers: { Authorization: `Bearer ${response.data.tokens}` }
        });
        setNotes(notesResponse.data);
        if (notesResponse.data.length > 0) {
          setActiveTab(notesResponse.data[0].id);
        }
      }
    } catch (err) {
      console.error('Error in auth callback:', err);
    }
  }, []);

  useEffect(() => {
    const checkAuth = async () => {
      const tokens = localStorage.getItem('googleTokens');
      if (tokens) {
        try {
          const response = await axios.get(`${API_URL}/api/notes`, {
            headers: { Authorization: `Bearer ${tokens}` }
          });
          setNotes(response.data);
          setIsAuthenticated(true);
          if (response.data.length > 0) {
            setActiveTab(response.data[0].id);
          }
        } catch (err) {
          console.error('Error fetching notes:', err);
        }
      }
      setIsLoading(false);
    };

    // Check for OAuth callback
    const urlParams = new URLSearchParams(window.location.search);
    const code = urlParams.get('code');
    if (code) {
      handleAuthCallback(code);
      // Remove the code from URL
      window.history.replaceState({}, document.title, '/');
    } else {
      checkAuth();
    }
  }, [handleAuthCallback]);

  const handleGoogleAuth = async () => {
    window.location.href = `${API_URL}/auth/google`;
  };

  const handleLogout = () => {
    localStorage.removeItem('googleTokens');
    setIsAuthenticated(false);
    setNotes([]);
    setActiveTab(null);
  };

  const handleSave = async () => {
    if (!activeTab) return;

    const note = notes.find(n => n.id === activeTab);
    if (!note) return;

    try {
      await axios.put(`${API_URL}/api/notes/${activeTab}`, {
        title: note.title,
        content: note.content
      }, {
        headers: { Authorization: `Bearer ${localStorage.getItem('googleTokens')}` }
      });
    } catch (err) {
      console.error('Error saving note:', err);
    }
  };

  const handleAddNote = async () => {
    try {
      const response = await axios.post(`${API_URL}/api/notes`, {
        title: 'New Note',
        content: ''
      }, {
        headers: { Authorization: `Bearer ${localStorage.getItem('googleTokens')}` }
      });

      setNotes([...notes, response.data]);
      setActiveTab(response.data.id);
    } catch (err) {
      console.error('Error creating note:', err);
    }
  };

  const handleNoteChange = (id, field, value) => {
    setNotes(notes.map(note => 
      note.id === id ? { ...note, [field]: value } : note
    ));
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center min-h-screen bg-gray-900">
        <motion.div
          initial={{ scale: 0.5, opacity: 0 }}
          animate={{ scale: 1, opacity: 1 }}
          transition={{ duration: 0.5 }}
          className="text-amber-500 text-4xl font-bold"
        >
          Loading...
        </motion.div>
      </div>
    );
  }

  if (!isAuthenticated) {
    return (
      <div className="flex flex-col items-center justify-center min-h-screen bg-gray-900 p-4">
        <motion.div
          initial={{ scale: 0.5, opacity: 0 }}
          animate={{ scale: 1, opacity: 1 }}
          transition={{ duration: 0.5 }}
          className="text-center"
        >
          <h1 className="text-4xl font-bold text-amber-500 mb-8">Welcome to Notes</h1>
          <button
            onClick={handleGoogleAuth}
            className="flex items-center gap-2 bg-amber-500 text-gray-900 px-6 py-3 rounded-lg font-medium hover:bg-amber-400 transition-colors"
          >
            <img src="https://www.google.com/favicon.ico" alt="Google" className="w-5 h-5" />
            Sign in with Google
          </button>
        </motion.div>
      </div>
    );
  }

  return (
    <div className="flex h-screen bg-gray-900 text-white">
      {/* Sidebar */}
      <motion.div
        initial={{ x: -300 }}
        animate={{ x: sidebarOpen ? 0 : -300 }}
        className="w-64 bg-gray-800 border-r border-gray-700"
      >
        <div className="p-4">
          <button
            onClick={handleAddNote}
            className="w-full flex items-center gap-2 bg-amber-500 text-gray-900 px-4 py-2 rounded-lg font-medium hover:bg-amber-400 transition-colors"
          >
            <Plus size={20} />
            New Note
          </button>
        </div>
        <div className="mt-4">
          {notes.map(note => (
            <button
              key={note.id}
              onClick={() => setActiveTab(note.id)}
              className={`w-full text-left px-4 py-2 flex items-center gap-2 ${
                activeTab === note.id ? 'bg-amber-500 text-gray-900' : 'hover:bg-gray-700'
              }`}
            >
              <FileText size={20} />
              {note.title}
            </button>
          ))}
        </div>
      </motion.div>

      {/* Main Content */}
      <div className="flex-1 flex flex-col">
        {/* Header */}
        <div className="h-16 bg-gray-800 border-b border-gray-700 flex items-center justify-between px-4">
          <button
            onClick={() => setSidebarOpen(!sidebarOpen)}
            className="text-gray-400 hover:text-white"
          >
            {sidebarOpen ? <X size={24} /> : <Menu size={24} />}
          </button>
          <div className="flex items-center gap-4">
            <button
              onClick={handleSave}
              className="flex items-center gap-2 bg-amber-500 text-gray-900 px-4 py-2 rounded-lg font-medium hover:bg-amber-400 transition-colors"
            >
              <Save size={20} />
              Save
            </button>
            <button
              onClick={handleLogout}
              className="text-gray-400 hover:text-white"
            >
              <LogOut size={24} />
            </button>
          </div>
        </div>

        {/* Note Content */}
        <div className="flex-1 p-4">
          {activeTab ? (
            <div className="h-full flex flex-col">
              <input
                type="text"
                value={notes.find(n => n.id === activeTab)?.title || ''}
                onChange={(e) => handleNoteChange(activeTab, 'title', e.target.value)}
                className="bg-transparent text-2xl font-bold mb-4 outline-none"
                placeholder="Untitled"
              />
              <textarea
                ref={textareaRef}
                value={notes.find(n => n.id === activeTab)?.content || ''}
                onChange={(e) => handleNoteChange(activeTab, 'content', e.target.value)}
                className="flex-1 bg-transparent outline-none resize-none"
                placeholder="Start writing..."
              />
            </div>
          ) : (
            <div className="h-full flex items-center justify-center text-gray-500">
              Select a note or create a new one
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

export default App;
